Local _QVias

With Thisform.Pagina.Dados.PagDados.pgBoleto 
	_QVias = .ChkVia1.Value 	   + ;
			 .ChkVia2.Value  * 2   + ;
			 .ChkVia3.Value  * 4   + ;
			 .ChkVia4.Value  * 8   + ;
			 .ChkVia5.Value  * 16  + ;
			 .ChkVia6.Value  * 32  + ;
			 .ChkVia7.Value  * 64  + ;
			 .ChkVia8.Value  * 128 + ;
			 .ChkVia9.Value  * 256 + ;
			 .ChkVia10.Value * 512
EndWith

Replace crSigOpCdc.QVias With _QVias

With This.Parent.Parent.SubNivel.Pageframe1.Page1
	Return Inlist( ThisForm.pcEscolha, 'INSERIR', 'ALTERAR' ) And ;
			.Op_subn.value = 1 And ;
			.Op_bxauto.value # 1 And .Op_itauto.value = 1 And .Op_bxsn.value # 1 And ;
			.Op_bxparcial.value = 1 And !Inlist( .Get_porcs.value, 0, 100 )
EndWith

Return Inlist( ThisForm.pcEscolha, 'INSERIR', 'ALTERAR' ) And ;
ThisForm.Pagina.Dados.PagDados.PgOperacao.Op_cai.Value = 1 And ;
ThisForm.Pagina.Dados.Op_Par.Value = 1 And ThisForm.PermiteAlt

If This.Value = 4 And InList(ThisForm.Pagina.Dados.Get_NFiscal.Value,1,2) ;
	And (This.Parent.Parent.PgOperacao.Op_Numeração.Value = 3 Or ;
		 This.Parent.Parent.PgFiscal.optAgrupas.Value = 1 )
	MessageBox('Configuração Errada!!!. operação emite Nota Fiscal',0+16,'')
	This.Value = 2
Endif

Return Inlist( ThisForm.pcEscolha, 'INSERIR', 'ALTERAR' ) And InList(This.Parent.Op_subn.value,1,4) And ;
			This.Parent.Op_bxauto.value # 1 And This.Parent.Op_itauto.value = 1 And ;
			This.Parent.Op_bxsn.value # 1 And ;
			This.Parent.Op_bxparcial.value = 1

If This.Value > 0
	MessageBox('Operação   : Dupla '+Chr(13)+;
			   'Op.Estoque : correspondente ao item'+Chr(13)+;
			   'Op.Padrão  : S ',0+48,'Atenção: Configuração necessária')

	Return .t.
EndIf
